CREATE OR REPLACE FUNCTION etidealcrm.is_active_user() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = etidealcrm AS $$ SELECT EXISTS (SELECT 1 FROM etidealcrm.profile p WHERE p.id = (SELECT auth.uid()) AND p.is_active); $$;
CREATE OR REPLACE FUNCTION etidealcrm.app_current_role() RETURNS etidealcrm.app_role LANGUAGE sql STABLE SECURITY DEFINER SET search_path = etidealcrm AS $$ SELECT p.role FROM etidealcrm.profile p WHERE p.id = (SELECT auth.uid()) AND p.is_active; $$;
CREATE OR REPLACE FUNCTION etidealcrm.current_dealership_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = etidealcrm AS $$ SELECT p.dealership_id FROM etidealcrm.profile p WHERE p.id = (SELECT auth.uid()) AND p.is_active; $$;
CREATE OR REPLACE FUNCTION etidealcrm.has_role(VARIADIC roles etidealcrm.app_role[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = etidealcrm AS $$ SELECT etidealcrm.app_current_role() = ANY (roles); $$;
CREATE OR REPLACE FUNCTION etidealcrm.is_device_authorized() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = etidealcrm AS $$
DECLARE hdr json; install text;
BEGIN
  IF NOT etidealcrm.is_active_user() THEN RETURN false; END IF;
  BEGIN hdr := current_setting('request.headers', true)::json; EXCEPTION WHEN OTHERS THEN RETURN true; END;
  IF hdr IS NULL THEN RETURN true; END IF;
  install := hdr ->> 'x-device-id';
  IF install IS NULL OR btrim(install) = '' THEN RETURN true; END IF;
  RETURN EXISTS (SELECT 1 FROM etidealcrm.device d WHERE d.user_id = (SELECT auth.uid()) AND d.install_id = install AND d.status = 'authorized');
END; $$;
CREATE OR REPLACE FUNCTION etidealcrm.can_read_leads() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = etidealcrm AS $$ SELECT etidealcrm.has_role('admin','owner','sales_manager','salesperson','used_manager','accounting','finance_insurance','marketing'); $$;
CREATE OR REPLACE FUNCTION etidealcrm.can_write_all_leads() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = etidealcrm AS $$ SELECT etidealcrm.has_role('admin','sales_manager'); $$;
